method below_threshold(l: seq<int>, t: int) returns (result: bool)
    // Precondition: The input list must be a valid sequence of integers
    requires |l| >= 0
    // Postcondition: The result is true if all elements in l are less than t, otherwise false
    ensures result == (forall x :: x in l ==> x < t)
{
    result := true;
    var i := 0;
    while i < |l|
        // Invariant: result is true if all elements checked so far are below t
        invariant result == (forall j :: 0 <= j < i ==> l[j] < t)
    {
        if l[i] >= t {
            result := false;
        }
        i := i + 1;
    }
}
